// Read-only ACL reconstruction after the original seeder: private has exactly
// current-owner SID1, while recordings retains initializer owner+SYSTEM SID2.
// Container/Object inheritance flags are normal; IsInherited must remain false.
// No Set-Acl, icacls, account-store or credential read occurs here.
const aclEnv=Object.fromEntries(Object.entries(process.env).filter(([key])=>key.toLowerCase()!=='psmodulepath'));
const acl={};
for(const name of ['private','recordings']){
 const target=path.join(ROOT,name),literal=target.replaceAll("'","''"),expectedCount=name==='private'?1:2;
 const expectedSids=name==='private'?'@($taskOwner.Value)':'@($taskOwner.Value,$taskSystem.Value)';
 const command="$ErrorActionPreference='Stop';$taskOwner=[Security.Principal.WindowsIdentity]::GetCurrent().User;$taskSystem=[Security.Principal.SecurityIdentifier]::new('S-1-5-18');$taskApplied=Get-Acl -LiteralPath '"+literal+"';$taskAllowed="+expectedSids+";$taskRules=@($taskApplied.GetAccessRules($true,$true,[Security.Principal.SecurityIdentifier]));$taskActualSids=@($taskRules|ForEach-Object {$_.IdentityReference.Value}|Sort-Object -Unique);if(-not $taskApplied.AreAccessRulesProtected -or $taskApplied.GetOwner([Security.Principal.SecurityIdentifier]).Value -ne $taskOwner.Value -or $taskRules.Count -ne "+expectedCount+" -or $taskActualSids.Count -ne "+expectedCount+" -or @($taskRules|Where-Object {$_.IsInherited -or $_.IdentityReference.Value -notin $taskAllowed -or $_.AccessControlType -ne [Security.AccessControl.AccessControlType]::Allow -or $_.FileSystemRights -ne [Security.AccessControl.FileSystemRights]::FullControl}).Count){throw 'Existing private/recordings exact-SID FullControl ACL verification failed'};@{ownerOnlyVerified=$true;allowedPrincipalCount=$taskRules.Count}|ConvertTo-Json -Compress";
 acl[name]=JSON.parse(execFileSync('powershell.exe',['-NoProfile','-NonInteractive','-Command',command],{encoding:'utf8',windowsHide:true,env:aclEnv,timeout:30000}));
 assert.equal(acl[name].ownerOnlyVerified,true);assert.equal(acl[name].allowedPrincipalCount,expectedCount);
}
